        "endDate": new Date(new Date().setDate(new Date().getDate() - (new Date().getDay() || 7) + 5)).toLocaleDateString("en-CA"),
        "academicYearId": await getAcademicYearId(),
        "isAllDayPeriods": false,
        "onlySelectedSlots": true,
